def transform(grid):
    h, w = len(grid), len(grid[0])

    # Find the full-width and full-height separator lines.
    sep_rows = [r for r, row in enumerate(grid)
                if row[0] != 0 and all(x == row[0] for x in row)]
    sep_cols = [c for c in range(w)
                if grid[0][c] != 0 and all(grid[r][c] == grid[0][c] for r in range(h))]

    row_ranges = []
    start = 0
    for r in sep_rows:
        row_ranges.append((start, r))
        start = r + 1
    row_ranges.append((start, h))

    col_ranges = []
    start = 0
    for c in sep_cols:
        col_ranges.append((start, c))
        start = c + 1
    col_ranges.append((start, w))

    # The non-background shape in the other compartments is the template.
    pattern = set()
    for r0, r1 in row_ranges:
        for c0, c1 in col_ranges[1:]:
            for r in range(r0, r1):
                for c in range(c0, c1):
                    if grid[r][c] != 0:
                        pattern.add((r - r0, c - c0))

    out = [[0] * w for _ in range(h)]

    # Preserve separator lines.
    for r in sep_rows:
        out[r] = grid[r][:]
    for c in sep_cols:
        for r in range(h):
            out[r][c] = grid[r][c]

    # Paint the template in every compartment using that row's color.
    for r0, r1 in row_ranges:
        color = next((grid[r][c] for r in range(r0, r1)
                      for c in range(col_ranges[0][0], col_ranges[0][1])
                      if grid[r][c] != 0), 0)
        if color:
            for c0, c1 in col_ranges:
                for dr, dc in pattern:
                    if r0 + dr < r1 and c0 + dc < c1:
                        out[r0 + dr][c0 + dc] = color

    return out
